from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R1 import SiteReset22R1
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R2 import SiteReset22R2
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R3 import SiteReset22R3
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R4 import SiteReset22R4
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_23R1 import SiteReset23R1


class SiteResetFactory(OperationFactoryPrototype):
    def __init__(self):
        super(SiteResetFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for site reset operation.
        :return: dictionary with timeout, requirement and operation description for site reset
        :rtype: dict
        """

        if self.bts.stream == "SBTS22R1":
            return SiteReset22R1(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R2":
            return SiteReset22R2(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R3":
            return SiteReset22R3(self.bts).get_kpi()

        elif self.bts.stream == "SBTS22R4":
            return SiteReset22R4(self.bts).get_kpi()

        elif self.bts.stream >= "SBTS23R1":
            return SiteReset23R1(self.bts).get_kpi()
